from abc import ABC, abstractmethod
from typing import Dict, List, Optional, Union


class TranscribeCommand(ABC):
    """Abstract base class for transcription commands."""

    @abstractmethod
    def execute(self, audio_path: str) -> Dict:
        """Execute the command and return a result dict."""
        pass


class DiarizationCommand(ABC):
    """Abstract base class for diarization commands."""

    @abstractmethod
    def execute(self, audio_path: str) -> Dict:
        """Execute the command and return diarization data."""
        pass


class LiveCommand(ABC):
    """Abstract base class for live transcription commands."""

    @abstractmethod
    def execute(self) -> None:
        """Execute the live command."""
        pass
